#!/usr/bin/env python3
"""
deployer_fix.py (v2) — Deploiement EN UNE COMMANDE : correctif geo-blocage
+ PLAFOND de collecte Job Bank + diagnostic complet embarque.

Nouveau en v2 :
  * jobbank_ca.collecter() plafonne a `limite` offres. Le flux Atom ignore
    le parametre rows et renvoie ~100 entrees ; sans plafond, 100 pages de
    detail etaient ouvertes a 1,2 s d'intervalle = 2 a 4 min de chargement
    silencieux — la vraie cause du '0 offre' dans Streamlit.
  * scripts/diag_complet.py est embarque et installe par ce script.

Deploiement du correctif geo-blocage,
avec sauvegarde automatique et retour arriere.

Ce que fait `python scripts/deployer_fix.py` :
  1. SAUVEGARDE  backups/avant-fix-<horodatage>.tar.gz
                 (app/api/sources/, jobs_api.py, offres_sync.py, mobilite.db)
  2. ECRIT       les 6 fichiers du registre de sources (contrat + adaptateurs),
                 embarques ici en base64 — aucun telechargement, aucun heredoc.
  3. PATCHE      jobs_api.py : le lien n'est montre au visiteur que si la
                 source le sert depuis l'etranger (Adzuna: non, Job Bank: oui).
                 L'admin voit toujours tout.
  4. PURGE       jobs_cache (les offres en cache n'ont pas le nouveau champ).
  5. VERIFIE     la syntaxe de chaque fichier ecrit ; restaure en cas d'echec.

Retour arriere :
    python scripts/deployer_fix.py --restaurer            # derniere sauvegarde
    python scripts/deployer_fix.py --restaurer backups/avant-fix-XXXX.tar.gz

Idempotent : relancable sans degat.
    python scripts/deployer_fix.py --dry                  # montre sans ecrire
"""
from __future__ import annotations

import ast
import base64
import re
import sqlite3
import sys
import tarfile
from datetime import datetime
from pathlib import Path

VERSION = "v3 — pagination a cout constant + diag sans faux positifs"
RACINE = Path(__file__).resolve().parent.parent
DRY = "--dry" in sys.argv
HORO = datetime.now().strftime("%Y%m%d-%H%M%S-%f")

PAYLOAD = {
 "app/api/sources/__init__.py": "",
 "app/api/sources/base.py": "",
 "app/api/sources/registre.py": "",
 "app/api/sources/jobbank_ca.py": "",
 "app/api/sources/adzuna.py": "",
 "app/api/sources/_modele.py": "",
 "scripts/diag_complet.py": ""
}

A_SAUVER = [
    "app/api/sources",
    "app/api/jobs_api.py",
    "app/api/offres_sync.py",
    "data/mobilite.db",
]

GARDE_AVANT = re.compile(r'if o\["url"\] and \(admin or _liens\):')
GARDE_APRES = ('if o.get("url") and '
               '(admin or (_liens and o.get("lien_accessible", True))):')


def sauvegarder() -> Path:
    dossier = RACINE / "backups"
    dossier.mkdir(exist_ok=True)
    archive = dossier / f"avant-fix-{HORO}.tar.gz"
    i = 0
    while archive.exists():                      # jamais ecraser une sauvegarde
        i += 1
        archive = dossier / f"avant-fix-{HORO}-{i}.tar.gz"
    with tarfile.open(archive, "w:gz") as tar:
        for rel in A_SAUVER:
            p = RACINE / rel
            if p.exists():
                tar.add(p, arcname=rel)
    print(f"  sauvegarde : {archive.relative_to(RACINE)}")
    return archive


def restaurer(archive: Path) -> None:
    print(f"  restauration depuis {archive.name} ...")
    with tarfile.open(archive, "r:gz") as tar:
        tar.extractall(RACINE)
    print("  restaure. Relance : yorbity")


def ecrire_sources() -> int:
    n = 0
    for rel, b64 in PAYLOAD.items():
        cible = RACINE / rel
        contenu = base64.b64decode(b64)
        if cible.exists() and cible.read_bytes() == contenu:
            continue
        if DRY:
            print(f"  ~ {rel} [DRY-RUN]")
            n += 1
            continue
        cible.parent.mkdir(parents=True, exist_ok=True)
        cible.write_bytes(contenu)
        try:
            ast.parse(contenu.decode("utf-8"))
        except SyntaxError as e:
            print(f"  x {rel} : syntaxe cassee ligne {e.lineno} — ABANDON")
            raise SystemExit(1)
        print(f"  v {rel}")
        n += 1
    if n == 0:
        print("  = fichiers sources deja a jour")
    return n


def patcher_jobs_api() -> None:
    p = RACINE / "app" / "api" / "jobs_api.py"
    if not p.exists():
        print("  ? jobs_api.py introuvable — patch du lien saute")
        return
    src = p.read_text(encoding="utf-8")
    if GARDE_APRES in src:
        print("  = jobs_api.py : garde du lien deja patche")
        return
    if not GARDE_AVANT.search(src):
        print("  ? jobs_api.py : ligne `if o[\"url\"] and (admin or _liens):` "
              "introuvable — patch saute (verifie manuellement)")
        return
    if DRY:
        print("  ~ jobs_api.py : 1 patch [DRY-RUN]")
        return
    src = GARDE_AVANT.sub(GARDE_APRES, src, count=1)
    try:
        ast.parse(src)
    except SyntaxError as e:
        print(f"  x jobs_api.py : syntaxe cassee ligne {e.lineno} — non ecrit")
        raise SystemExit(1)
    p.write_text(src, encoding="utf-8")
    print("  v jobs_api.py : garde du lien patche")


def purger_cache() -> None:
    db = RACINE / "data" / "mobilite.db"
    if not db.exists():
        print("  - pas de base, pas de cache a purger")
        return
    if DRY:
        print("  ~ jobs_cache : purge [DRY-RUN]")
        return
    try:
        con = sqlite3.connect(db, timeout=30)
        n = con.execute("DELETE FROM jobs_cache").rowcount
        con.commit()
        con.close()
        print(f"  v jobs_cache : {n} entree(s) purgee(s)")
    except sqlite3.OperationalError as e:
        print(f"  ? cache non purge ({e}) — ferme Streamlit puis relance ce script")


def test_fumee() -> None:
    """Collecte 2 offres Job Bank REELLES pour prouver que la chaine marche.
    ~8-12 s (delai de politesse). En cas d'echec, montre l'erreur au lieu
    de laisser Streamlit echouer en silence."""
    print("\nTEST FUMEE — collecte de 2 offres Job Bank (patiente ~10 s) ...")
    import time
    import traceback
    sys.path.insert(0, str(RACINE / "app" / "api"))
    sys.path.insert(0, str(RACINE))
    try:
        from sources import registre
        t0 = time.time()
        offres = registre.collecter("CA", "metier", limite=2)
        duree = time.time() - t0
        jb = [o for o in offres if o.get("source") == "jobbank_ca"]
        print(f"  {len(offres)} offre(s) en {duree:.1f} s, dont {len(jb)} Job Bank :")
        for o in offres:
            lien = "lien visible" if o.get("lien_accessible") else "lien masque"
            print(f"    [{o.get('source','?'):10}] {o.get('titre','')[:38]:40} "
                  f"{o.get('reference','')}  ({lien})")
        if not jb:
            print("  [!] AUCUNE offre Job Bank — lance :"
                  " python scripts/diag_complet.py --llm llama3.2:3b")
    except Exception:
        print("  ECHEC du test — voici l'erreur exacte :")
        traceback.print_exc()
        print("  -> python scripts/diag_complet.py pour le rapport complet.")


def main() -> None:
    if "--restaurer" in sys.argv:
        i = sys.argv.index("--restaurer")
        if i + 1 < len(sys.argv) and not sys.argv[i + 1].startswith("-"):
            archive = RACINE / sys.argv[i + 1]
        else:
            candidates = sorted((RACINE / "backups").glob("avant-fix-*.tar.gz"))
            if not candidates:
                print("Aucune sauvegarde dans backups/")
                sys.exit(1)
            archive = candidates[-1]
        if not archive.exists():
            print(f"Archive introuvable : {archive}")
            sys.exit(1)
        restaurer(archive)
        return

    print(f"deployer_fix {VERSION}")
    if DRY:
        print(">>> DRY-RUN : rien ne sera ecrit\n")
    else:
        sauvegarder()
    ecrire_sources()
    patcher_jobs_api()
    purger_cache()
    print()
    if "--test" in sys.argv and not DRY:
        test_fumee()
    print()
    print("FINI. Relance : yorbity")
    print(f"Retour arriere : python scripts/deployer_fix.py --restaurer")


if __name__ == "__main__":
    main()
